@@ -0,0 +1,28 @@
+// Sites: each location belongs to one site, and batches are at a site through
+// their location. Stock, cooking, alerts and stock-takes work per site.
+import { AppError } from "../errors.js";
+
+/** The site used when a request names none. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The locations of a site. */
+export function siteLocations(store, site = DEFAULT_SITE) {
+  return store.data.locations.filter((l) => l.site === site);
+}
+
+/** True when a location id exists and belongs to `site`. */
+export function hasLocation(store, location, site = DEFAULT_SITE) {
+  return siteLocations(store, site).some((l) => l.id === location);
+}
+
+/** True when a batch is stored at a location of `site`. */
+export function batchInSite(store, batch, site = DEFAULT_SITE) {
+  return hasLocation(store, batch.location, site);
+}
