--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,59 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+const post = (handle, path, body, headers = {}) => handle({ method: "POST", path, body, headers });
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "nowhere" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+});
+
+test("without the header the site is main", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items" });
+  assert.equal(res.body.find((i) => i.id === 1).onHand, 10);
+});
+
+test("the annex sees no main stock, alerts or value", async () => {
+  const { handle } = app();
+  const items = await handle({ path: "/items", headers: annex });
+  assert.ok(items.body.every((i) => i.onHand === 0));
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 0);
+  assert.deepEqual((await handle({ path: "/alerts", headers: annex })).body.expiring, []);
+  assert.ok((await handle({ path: "/alerts", headers: annex })).body.lowStock.length > 0);
+});
+
+test("cooking at the annex cannot use main stock", async () => {
+  const { handle, store } = app();
+  const m0 = store.data.movements.length;
+  const res = await post(handle, "/recipes/1/cook", { portions: 2 }, annex);
+  assert.equal(res.status, 409);
+  assert.equal(store.data.movements.length, m0);
+});
+
+test("stock received into the annex is only seen there", async () => {
+  const { handle } = app();
+  const order = (await post(handle, "/orders", { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] })).body;
+  await post(handle, `/orders/${order.id}/send`, null);
+  const lots = { lots: [{ lot: "A-1", expires: null, location: "annex-fridge" }] };
+  assert.equal((await post(handle, `/orders/${order.id}/receive`, lots)).status, 400);
+  const ok = await post(handle, `/orders/${order.id}/receive`, lots, annex);
+  assert.equal(ok.status, 200);
+  assert.equal((await handle({ path: "/items/1", headers: annex })).body.onHand, 3);
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+});
+
+test("stock-takes only see their own site", async () => {
+  const { handle } = app();
+  assert.equal((await post(handle, "/stocktakes", { location: "annex-fridge" })).body.error.code, "unknown_location");
+  assert.equal((await post(handle, "/stocktakes", { location: "dry" }, annex)).body.error.code, "unknown_location");
+  const take = (await post(handle, "/stocktakes", { location: "annex-fridge" }, annex)).body;
+  assert.equal(take.state, "open");
+  assert.equal((await post(handle, `/stocktakes/${take.id}/finish`, null)).status, 404);
+});
